354	// --- HTTP
355	
356	/// One request as it came off the socket, with what the frame needs
357	/// and nothing it does not: the bearer token is taken out of the
358	/// headers so it is never logged with them.
359	#[derive(Debug, Clone, PartialEq, Eq)]
360	pub struct RemoteRequest {
361	    pub method: String,
362	    /// The path without its query string.
363	    pub path: String,
364	    /// The query string's pairs, undecoded: ids and numbers only.
365	    pub query: Vec<(String, String)>,
366	    pub body: Vec<u8>,
367	    /// The `Authorization: Bearer` value, if any.
368	    pub bearer: Option<String>,
369	    /// The `Sec-WebSocket-Key` of a request that asks to upgrade to a
370	    /// WebSocket; the frame answers [`SUBSCRIBED`] to accept it.
371	    pub upgrade: Option<String>,
372	}
373	
374	impl RemoteRequest {
375	    /// The first value of a query parameter.
376	    #[must_use]
377	    pub fn param(&self, name: &str) -> Option<&str> {
378	        self.query
379	            .iter()
380	            .find(|(n, _)| n == name)
381	            .map(|(_, v)| v.as_str())
382	    }
383	}
384	
385	/// What the frame answers: a status and a JSON body, and whether the
386	/// request was made by a paired device, which moves the connection
387	/// from the unauthenticated pool to the paired one.
388	#[derive(Debug, Clone, PartialEq, Eq)]
389	pub struct RemoteReply {
390	    pub status: u16,
391	    pub body: Vec<u8>,
392	    pub authenticated: bool,
393	}
394	
395	/// One request off a connection, with the channel its reply goes back
396	/// on and, for an upgrade request, the queue the connection will feed
397	/// its WebSocket from once the frame accepts.
398	pub struct RemoteIncoming {
399	    pub request: RemoteRequest,
400	    pub reply: SyncSender<RemoteReply>,
401	    pub subscriber: Option<SubscriberQueue>,
402	}
403	
404	/// The status the frame answers an upgrade request with to accept it;
405	/// the connection thread then writes the 101 and becomes a subscriber.
406	pub const SUBSCRIBED: u16 = 101;
407	
408	/// How many events a subscriber may fall behind before it is dropped.
409	pub const SUBSCRIBER_QUEUE: usize = 256;
410	
411	/// How long a subscriber's thread waits for an event before it looks
412	/// for a frame from the device (a close, a ping, a `watch`).
413	const SUBSCRIBER_POLL: Duration = Duration::from_millis(50);
414	
415	/// The frame's end of a subscriber: events go in as JSON text; a full
416	/// queue drops the sender with `overflow` set, which the connection
417	/// thread turns into `resync_required` and a close. `id` names the
418	/// subscriber in the frames it sends back.
419	pub struct SubscriberQueue {
420	    pub id: u64,
421	    pub tx: SyncSender<String>,
422	    pub overflow: Arc<AtomicBool>,
423	}
424	
425	/// A text frame a subscribed device sent (`watch`, `unwatch`), or
426	/// `None` once its socket ended, however it ended.
427	pub struct SubscriberFrame {
428	    pub subscriber: u64,
429	    pub text: Option<String>,
430	}
431	
432	/// How many device frames may wait for the frame thread.
433	const FRAMES: usize = 64;
434	
435	/// The most a request line and its headers may take, and the most a
436	/// body may be.
437	pub const MAX_HEAD: usize = 8 * 1024;
438	pub const MAX_BODY: usize = 64 * 1024;
439	
440	/// The head of one HTTP/1.1 request: method, target, lowercased
441	/// headers, body. `None` at a clean end of stream before any byte; an
442	/// oversized or malformed request is an error that closes the
443	/// connection.
444	fn read_request<R: Read>(reader: &mut BufReader<R>) -> io::Result<Option<RemoteRequest>> {
445	    let mut line = String::new();
446	    if reader.read_line(&mut line)? == 0 {
447	        return Ok(None);
448	    }
449	    let mut parts = line.split_whitespace();
450	    let (Some(method), Some(target)) = (parts.next(), parts.next()) else {
451	        return Err(io::Error::new(
452	            io::ErrorKind::InvalidData,
453	            "bad request line",
454	        ));
455	    };
456	    let mut headers: Vec<(String, String)> = Vec::new();
457	    let mut total = line.len();
458	    loop {
459	        let mut h = String::new();
460	        if reader.read_line(&mut h)? == 0 {
461	            return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "headers cut"));
462	        }
463	        total += h.len();
464	        if total > MAX_HEAD {
465	            return Err(io::Error::new(io::ErrorKind::InvalidData, "head too large"));
466	        }
467	        let h = h.trim_end();
468	        if h.is_empty() {
469	            break;
470	        }
471	        if let Some((n, v)) = h.split_once(':') {
472	            headers.push((n.trim().to_ascii_lowercase(), v.trim().to_owned()));
473	        }
474	    }
475	    let header = |name: &str| {
476	        headers
477	            .iter()
478	            .find(|(n, _)| n == name)
479	            .map(|(_, v)| v.as_str())
480	    };
481	    let length: usize = header("content-length")
482	        .and_then(|v| v.parse().ok())
483	        .unwrap_or(0);
484	    if length > MAX_BODY {
485	        return Err(io::Error::new(io::ErrorKind::InvalidData, "body too large"));
486	    }
487	    let bearer = header("authorization")
488	        .and_then(|v| v.strip_prefix("Bearer "))
489	        .map(|t| t.trim().to_owned())
490	        .filter(|t| !t.is_empty());
491	    let upgrade = header("upgrade")
492	        .filter(|u| u.eq_ignore_ascii_case("websocket"))
493	        .and_then(|_| header("sec-websocket-key"))
494	        .map(str::to_owned);
495	    let (path, query) = target.split_once('?').unwrap_or((target, ""));
496	    let query = query
497	        .split('&')
498	        .filter(|s| !s.is_empty())
499	        .map(|pair| {
500	            let (n, v) = pair.split_once('=').unwrap_or((pair, ""));
501	            (n.to_owned(), v.to_owned())
502	        })
503	        .collect();
504	    let mut body = vec![0; length];
505	    reader.read_exact(&mut body)?;
506	    Ok(Some(RemoteRequest {
507	        method: method.to_owned(),
508	        path: path.to_owned(),
509	        query,
510	        body,
511	        bearer,
512	        upgrade,
513	    }))
514	}
515	
516	/// The 101 that switches a connection to WebSocket. The request was
517	/// already read by `read_request`, so `tungstenite::accept` cannot be
518	/// used; the stream is wrapped with `from_raw_socket` after this.
519	fn respond_upgrade<W: Write>(w: &mut W, key: &str) -> io::Result<()> {
520	    write!(
521	        w,
522	        "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {}\r\n\r\n",
523	        tungstenite::handshake::derive_accept_key(key.as_bytes())
524	    )?;
525	    w.flush()
526	}
527	
528	/// Write one response. Head and body in one write, so a reply is one
529	/// TLS record and one segment.
530	fn respond<W: Write>(w: &mut W, status: u16, body: &[u8]) -> io::Result<()> {
531	    let reason = match status {
532	        200 => "OK",
533	        400 => "Bad Request",
534	        401 => "Unauthorized",
535	        403 => "Forbidden",
536	        404 => "Not Found",
537	        405 => "Method Not Allowed",
538	        413 => "Content Too Large",
539	        429 => "Too Many Requests",
540	        503 => "Service Unavailable",
541	        504 => "Gateway Timeout",
542	        _ => "Error",
543	    };
544	    let mut out = format!(
545	        "HTTP/1.1 {status} {reason}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: keep-alive\r\n\r\n",
546	        body.len()
547	    )
548	    .into_bytes();
549	    out.extend_from_slice(body);
550	    w.write_all(&out)?;
551	    w.flush()
552	}
553	
554	/// The error body the connection thread sends for what never reaches
555	/// the frame.
556	fn error_body(code: &str, message: &str) -> Vec<u8> {
557	    serde_json::json!({ "error": { "code": code, "message": message } })
558	        .to_string()
559	        .into_bytes()
560	}
561	
562	// --- the listener
563	
564	/// At most 16 connections, 4 of them unauthenticated. The 4 are a pool
565	/// of their own: a flood of strangers fills its own slots and never a
566	/// paired device's.
567	pub const MAX_UNAUTHENTICATED: usize = 4;
568	pub const MAX_PAIRED: usize = 12;
569	/// The TLS handshake and the first request line within this.
570	const HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(5);
571	/// A paired device polling on a kept connection may sit idle this long
572	/// between requests.
573	const IDLE_TIMEOUT: Duration = Duration::from_secs(30);
574	const WRITE_TIMEOUT: Duration = Duration::from_secs(10);
575	/// How long a connection waits for the frame's answer. The frame
576	/// answers on its next pass, so this only matters if it has stalled.
577	pub(crate) const ANSWER_TIMEOUT: Duration = Duration::from_secs(60);
578	/// The frame drains at most this many requests per pass from a channel
579	/// this deep; a full channel answers 503 without reaching the frame.
580	pub const DRAIN_PER_PASS: usize = 8;
581	const INBOX: usize = 64;
582	/// `/pair` and `/info` per minute per listener, answered 429 past it.
583	const PAIR_PER_MINUTE: usize = 6;
584	const INFO_PER_MINUTE: usize = 60;
585	
586	const PAIR_PATH: &str = "/api/v1/pair";
587	const INFO_PATH: &str = "/api/v1/info";
588	
589	#[derive(Default)]
590	struct Pools {
591	    unauthenticated: AtomicUsize,
592	    paired: AtomicUsize,
593	}
594	
595	/// Allows `max` events per `per`, counted on a sliding window.
596	struct RateWindow {
597	    stamps: VecDeque<Instant>,
598	    max: usize,
599	    per: Duration,
600	}
601	
602	impl RateWindow {
603	    fn new(max: usize, per: Duration) -> Self {
604	        Self {
605	            stamps: VecDeque::new(),
606	            max,
607	            per,
608	        }
609	    }
610	
611	    fn allow(&mut self, now: Instant) -> bool {
612	        while self.stamps.front().is_some_and(|&t| now - t >= self.per) {
613	            self.stamps.pop_front();
614	        }
615	        if self.stamps.len() >= self.max {
616	            return false;
617	        }
618	        self.stamps.push_back(now);
619	        true
620	    }
621	}
622	
623	struct Limits {
624	    pair: Mutex<RateWindow>,
625	    info: Mutex<RateWindow>,
626	}
627	
628	impl Limits {
629	    /// Whether a request for `path` is over its window; a poisoned lock
630	    /// counts as over, never as open.
631	    fn limited(&self, path: &str) -> bool {
632	        let window = match path {
633	            PAIR_PATH => &self.pair,
634	            INFO_PATH => &self.info,
635	            _ => return false,
636	        };
637	        !window.lock().map_or(true, |mut w| w.allow(Instant::now()))
638	    }
639	}
640	
641	/// What every connection thread shares.
642	struct Shared {
643	    tls: Arc<ServerConfig>,
644	    requests: SyncSender<RemoteIncoming>,
645	    frames: SyncSender<SubscriberFrame>,
646	    wake: Arc<dyn Fn() + Send + Sync>,
647	    pools: Pools,
648	    limits: Limits,
649	    next_subscriber: AtomicU64,
650	}
651	
652	/// The TLS listener: an accept thread, one thread per connection,
653	/// requests handed to the frame over a bounded channel. Bound only by
654	/// the instance that holds the store lock.
655	pub struct RemotePort {
656	    addr: SocketAddr,
657	    requests: Receiver<RemoteIncoming>,
658	    frames: Receiver<SubscriberFrame>,
659	    stop: Arc<AtomicBool>,
660	    thread: Option<JoinHandle<()>>,
661	}
662	
663	impl RemotePort {
664	    /// Bind `addr` (port 0 picks one) with the host's TLS configuration.
665	    /// `wake` runs on a connection thread whenever a request is queued
666	    /// (an egui `request_repaint`).
667	    pub fn bind(
668	        addr: SocketAddr,
669	        tls: Arc<ServerConfig>,
670	        wake: impl Fn() + Send + Sync + 'static,
671	    ) -> io::Result<Self> {
672	        let listener = TcpListener::bind(addr)?;
673	        let addr = listener.local_addr()?;
674	        let (tx, requests) = mpsc::sync_channel(INBOX);
675	        let (frames_tx, frames) = mpsc::sync_channel(FRAMES);
676	        let stop = Arc::new(AtomicBool::new(false));
677	        let shared = Arc::new(Shared {
678	            tls,
679	            requests: tx,
680	            frames: frames_tx,
681	            wake: Arc::new(wake),
682	            pools: Pools::default(),
683	            limits: Limits {
684	                pair: Mutex::new(RateWindow::new(PAIR_PER_MINUTE, Duration::from_secs(60))),
685	                info: Mutex::new(RateWindow::new(INFO_PER_MINUTE, Duration::from_secs(60))),
686	            },
687	            next_subscriber: AtomicU64::new(1),
688	        });
689	        let thread = {
690	            let stop = Arc::clone(&stop);
691	            std::thread::Builder::new()
692	                .name("switchboard-remote".into())
693	                .spawn(move || {
694	                    for stream in listener.incoming() {
695	                        if stop.load(Ordering::SeqCst) {
696	                            break;
697	                        }
698	                        let Ok(stream) = stream else { continue };
699	                        // Past the pool a stranger is closed at once:
700	                        // dropping the stream is the close.
701	                        if shared.pools.unauthenticated.load(Ordering::SeqCst)
702	                            >= MAX_UNAUTHENTICATED
703	                        {
704	                            drop(stream);
705	                            continue;
706	                        }
707	                        shared.pools.unauthenticated.fetch_add(1, Ordering::SeqCst);
708	                        let shared = Arc::clone(&shared);
709	                        let _ = std::thread::Builder::new()
710	                            .name("switchboard-remote-conn".into())
711	                            .spawn(move || {
712	                                let paired = AtomicBool::new(false);
713	                                if let Err(e) = connection(stream, &shared, &paired) {
714	                                    log::debug!("remote connection: {e}");
715	                                }
716	                                if paired.load(Ordering::SeqCst) {
717	                                    shared.pools.paired.fetch_sub(1, Ordering::SeqCst);
718	                                } else {
719	                                    shared.pools.unauthenticated.fetch_sub(1, Ordering::SeqCst);
720	                                }
721	                            });
722	                    }
723	                })?
724	        };
725	        Ok(Self {
726	            addr,
727	            requests,
728	            frames,
729	            stop,
730	            thread: Some(thread),
731	        })
732	    }
733	
734	    /// Up to `max` requests that arrived since the last poll, in
735	    /// arrival order; the rest wait on the channel.
736	    pub fn poll(&mut self, max: usize) -> Vec<RemoteIncoming> {
737	        self.requests.try_iter().take(max).collect()
738	    }
739	
740	    /// Every frame subscribed devices sent since the last poll.
741	    pub fn poll_frames(&mut self) -> Vec<SubscriberFrame> {
742	        self.frames.try_iter().collect()
743	    }
744	
745	    #[must_use]
746	    pub fn addr(&self) -> SocketAddr {
747	        self.addr
748	    }
749	}
750	
751	impl Drop for RemotePort {
752	    fn drop(&mut self) {
753	        self.stop.store(true, Ordering::SeqCst);
754	        // The accept loop only checks the flag after a connection, so
755	        // make one to unblock it.
756	        let unblock = if self.addr.ip().is_unspecified() {
757	            SocketAddr::new(IpAddr::from([127, 0, 0, 1]), self.addr.port())
758	        } else {
759	            self.addr
760	        };
761	        let _ = TcpStream::connect_timeout(&unblock, Duration::from_secs(1));
762	        if let Some(t) = self.thread.take() {
763	            let _ = t.join();
764	        }
765	    }
766	}
767	
768	/// One connection: the handshake, then a request and a reply at a time
769	/// until the device hangs up or a deadline passes.
770	fn connection(tcp: TcpStream, shared: &Arc<Shared>, paired: &AtomicBool) -> io::Result<()> {
771	    tcp.set_read_timeout(Some(HANDSHAKE_TIMEOUT))?;
772	    tcp.set_write_timeout(Some(WRITE_TIMEOUT))?;
773	    // A reply is one record and goes out at once; Nagle with the
774	    // device's delayed ACK would otherwise add milliseconds per request.
775	    tcp.set_nodelay(true)?;
776	    let conn = ServerConnection::new(Arc::clone(&shared.tls)).map_err(io::Error::other)?;
777	    let mut stream = StreamOwned::new(conn, tcp);
778	    while stream.conn.is_handshaking() {
779	        stream.conn.complete_io(&mut stream.sock)?;
780	    }
781	    let mut reader = BufReader::new(stream);
782	    let mut first = true;
783	    while let Some(request) = read_request(&mut reader)? {
784	        if first {
785	            reader.get_ref().sock.set_read_timeout(Some(IDLE_TIMEOUT))?;
786	            first = false;
787	        }
788	        if shared.limits.limited(&request.path) {
789	            respond(
790	                reader.get_mut(),
791	                429,
792	                &error_body("rate_limited", "too many requests; try again in a minute"),
793	            )?;
794	            continue;
795	        }
796	        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
797	        let upgrade_key = request.upgrade.clone();
798	        let mut queue = None;
799	        let queue_for_frame = upgrade_key.as_ref().map(|_| {
800	            let (q_tx, q_rx) = mpsc::sync_channel::<String>(SUBSCRIBER_QUEUE);
801	            let overflow = Arc::new(AtomicBool::new(false));
802	            let id = shared.next_subscriber.fetch_add(1, Ordering::SeqCst);
803	            queue = Some((id, q_rx, Arc::clone(&overflow)));
804	            SubscriberQueue {
805	                id,
806	                tx: q_tx,
807	                overflow,
808	            }
809	        });
810	        if shared
811	            .requests
812	            .try_send(RemoteIncoming {
813	                request,
814	                reply: reply_tx,
815	                subscriber: queue_for_frame,
816	            })
817	            .is_err()
818	        {
819	            respond(
820	                reader.get_mut(),
821	                503,
822	                &error_body("busy", "the host is busy; try again"),
823	            )?;
824	            continue;
825	        }
826	        (shared.wake)();
827	        let reply = match reply_rx.recv_timeout(ANSWER_TIMEOUT) {
828	            Ok(reply) => reply,
829	            Err(_) => RemoteReply {
830	                status: 504,
831	                body: error_body("no_answer", "the app did not answer in time"),
832	                authenticated: false,
833	            },
834	        };
835	        if reply.authenticated && !paired.load(Ordering::SeqCst) {
836	            // The device moves from the unauthenticated pool to the
837	            // paired one on its first authenticated request.
838	            if shared.pools.paired.load(Ordering::SeqCst) >= MAX_PAIRED {
839	                respond(
840	                    reader.get_mut(),
841	                    503,
842	                    &error_body("full", "too many paired connections"),
843	                )?;
844	                return Ok(());
845	            }
846	            shared.pools.paired.fetch_add(1, Ordering::SeqCst);
847	            shared.pools.unauthenticated.fetch_sub(1, Ordering::SeqCst);
848	            paired.store(true, Ordering::SeqCst);
849	        }
850	        if reply.status == SUBSCRIBED
851	            && let (Some(key), Some((id, q_rx, overflow))) = (upgrade_key, queue)
852	        {
853	            respond_upgrade(reader.get_mut(), &key)?;
854	            let out = subscriber(reader.into_inner(), &q_rx, &overflow, id, shared);
855	            let ended = SubscriberFrame {
856	                subscriber: id,
857	                text: None,
858	            };
859	            if shared.frames.send(ended).is_ok() {
860	                (shared.wake)();
861	            }
862	            return out;
863	        }
864	        respond(reader.get_mut(), reply.status, &reply.body)?;
865	    }
866	    Ok(())
867	}
868	
869	/// Feed one WebSocket from its queue until the frame drops the queue
870	/// (a revocation, or an overflow, which ends with `resync_required`)
871	/// or the device closes. The socket is non-blocking: an event goes out
872	/// the moment it is queued, the device's own frames are looked for
873	/// only when there is nothing to send (a close ends the subscription,
874	/// a ping is answered by the library, a text frame goes to the frame
875	/// thread as a `SubscriberFrame`), and a device that stops reading
876	/// stalls only this thread, for `WRITE_TIMEOUT` at most, while the
877	/// frame fills and then drops its queue.
878	fn subscriber(
879	    stream: StreamOwned<ServerConnection, TcpStream>,
880	    events: &Receiver<String>,
881	    overflow: &AtomicBool,
882	    id: u64,
883	    shared: &Shared,
884	) -> io::Result<()> {
885	    stream.sock.set_nonblocking(true)?;
886	    let mut ws =
887	        tungstenite::WebSocket::from_raw_socket(stream, tungstenite::protocol::Role::Server, None);
888	    loop {
889	        match events.recv_timeout(SUBSCRIBER_POLL) {
890	            Ok(text) => {
891	                send_text(&mut ws, text)?;
892	                continue;
893	            }
894	            Err(mpsc::RecvTimeoutError::Timeout) => {}
895	            Err(mpsc::RecvTimeoutError::Disconnected) => {
896	                if overflow.load(Ordering::SeqCst) {
897	                    let _ = send_text(&mut ws, "{\"type\":\"resync_required\"}".into());
898	                }
899	                let _ = ws.close(None);
900	                let _ = flush_by(&mut ws, Instant::now() + WRITE_TIMEOUT);
901	                return Ok(());
902	            }
903	        }
904	        match ws.read() {
905	            Ok(tungstenite::Message::Close(_)) => return Ok(()),
906	            Ok(tungstenite::Message::Text(text)) => {
907	                let frame = SubscriberFrame {
908	                    subscriber: id,
909	                    text: Some(text.to_string()),
910	                };
911	                if shared.frames.try_send(frame).is_ok() {
912	                    (shared.wake)();
913	                }
914	            }
915	            Ok(_) => {}
916	            Err(tungstenite::Error::Io(e)) if e.kind() == io::ErrorKind::WouldBlock => {}
917	            Err(tungstenite::Error::ConnectionClosed | tungstenite::Error::AlreadyClosed) => {
918	                return Ok(());
919	            }
920	            Err(e) => return Err(io::Error::other(e.to_string())),
921	        }
922	    }
923	}
924	
925	type Socket = tungstenite::WebSocket<StreamOwned<ServerConnection, TcpStream>>;
926	
927	/// Queue one text frame and write it out, waiting up to `WRITE_TIMEOUT`
928	/// for a full socket to drain.
929	fn send_text(ws: &mut Socket, text: String) -> io::Result<()> {
930	    match ws.write(tungstenite::Message::Text(text.into())) {
931	        Ok(()) => {}
932	        Err(tungstenite::Error::Io(e)) if e.kind() == io::ErrorKind::WouldBlock => {}
933	        Err(e) => return Err(io::Error::other(e.to_string())),
934	    }
935	    flush_by(ws, Instant::now() + WRITE_TIMEOUT)
936	}
937	
938	/// Flush what is queued, retrying a full socket until `deadline`.
939	fn flush_by(ws: &mut Socket, deadline: Instant) -> io::Result<()> {
940	    loop {
941	        match ws.flush() {
942	            Ok(()) => return Ok(()),
943	            Err(tungstenite::Error::Io(e)) if e.kind() == io::ErrorKind::WouldBlock => {
944	                if Instant::now() >= deadline {
945	                    return Err(io::Error::new(
946	                        io::ErrorKind::TimedOut,
947	                        "the device stopped reading",
948	                    ));
949	                }
950	                std::thread::sleep(Duration::from_millis(5));
951	            }
952	            Err(e) => return Err(io::Error::other(e.to_string())),
953	        }
954	    }
955	}
956	
957	/// The address a device on the local network would reach this machine
958	/// at: the one the system routes outward on. No packet is sent; a
959	/// connected UDP socket only chooses a source address. `None` with no
960	/// network.
961	#[must_use]
962	pub fn local_address() -> Option<IpAddr> {
963	    let socket = UdpSocket::bind("0.0.0.0:0").ok()?;
964	    socket.connect("192.0.2.1:9").ok()?;
965	    socket
966	        .local_addr()
967	        .ok()
968	        .map(|a| a.ip())
969	        .filter(|ip| !ip.is_loopback())
970	}
971	
972	#[cfg(test)]
973	mod tests {
974	    use super::*;
975	
976	    #[test]
977	    fn an_identity_round_trips_and_its_key_hashes_to_its_spki() {
978	        let dir = tempfile::tempdir().unwrap();
979	        let files = RemoteFiles::new(dir.path().to_path_buf());
980	        assert_eq!(files.load_identity().unwrap(), None);
981	        assert!(files.load_devices().unwrap().is_empty());
982	        let (identity, key) = make_identity(None, "Sully's Mac", Listen::default()).unwrap();
983	        assert_eq!(spki_sha256_of_key(&key).unwrap(), identity.spki_sha256);
984	        let der = certificate_der(&identity).unwrap();
985	        assert_eq!(
986	            spki_sha256_of_cert(&der).as_deref(),
987	            Some(identity.spki_sha256.as_str())
988	        );
989	        files.save_identity(&identity).unwrap();
990	        assert_eq!(files.load_identity().unwrap(), Some(identity.clone()));
991	        let device = PairedDevice {
992	            id: Uuid::new_v4(),
993	            name: "Vision Pro".into(),
994	            scope: crate::ports::remote::Scope::Read,
995	            token_sha256: token_sha256("t"),
996	            created: SystemTime::UNIX_EPOCH,
997	            last_seen: None,
998	        };
999	        files.save_devices(std::slice::from_ref(&device)).unwrap();
1000	        assert_eq!(files.load_devices().unwrap(), vec![device]);
1001	        #[cfg(unix)]
1002	        {
1003	            use std::os::unix::fs::PermissionsExt;
1004	            let mode = std::fs::metadata(dir.path().join(DEVICES_FILE))
1005	                .unwrap()
1006	                .permissions()
1007	                .mode()
1008	                & 0o777;
1009	            assert_eq!(mode, 0o600);
1010	        }
1011	        // The same installation under a rotated key.
1012	        let (rotated, _) = make_identity(
1013	            Some(identity.server_id),
1014	            &identity.server_name,
1015	            Listen::default(),
1016	        )
1017	        .unwrap();
1018	        assert_eq!(rotated.server_id, identity.server_id);
1019	        assert_ne!(rotated.spki_sha256, identity.spki_sha256);
1020	        assert!(tls_config(&identity, &key).is_ok());
1021	    }
1022	
1023	    #[test]
1024	    fn a_malformed_file_is_an_error_not_a_fresh_start() {
1025	        let dir = tempfile::tempdir().unwrap();
1026	        std::fs::write(dir.path().join(IDENTITY_FILE), b"{not json").unwrap();
1027	        let files = RemoteFiles::new(dir.path().to_path_buf());
1028	        assert!(files.load_identity().is_err());
1029	    }
1030	
1031	    #[test]
1032	    fn codes_and_tokens_have_their_shapes() {
1033	        let code = pairing_code();
1034	        assert_eq!(code.len(), CODE_LENGTH);
1035	        assert!(code.bytes().all(|b| CODE_ALPHABET.contains(&b)));
1036	        assert!(!code.contains(['I', 'L', 'O', 'U']));
1037	        let token = bearer_token();
1038	        assert_eq!(token.len(), 43);
1039	        assert!(!token.contains(['=', '+', '/']));
1040	        assert_ne!(pairing_code(), code);
1041	        assert_eq!(token_sha256("abc").len(), 64);
1042	    }
1043	
1044	    #[test]
1045	    fn a_request_reads_with_its_query_bearer_and_body() {
1046	        let text = b"POST /api/v1/x?lines=5&a=b HTTP/1.1\r\nHost: h\r\nAuthorization: Bearer tok\r\nContent-Length: 2\r\n\r\nhi";
1047	        let mut r = BufReader::new(&text[..]);
1048	        let req = read_request(&mut r).unwrap().unwrap();
1049	        assert_eq!(req.method, "POST");
1050	        assert_eq!(req.path, "/api/v1/x");
1051	        assert_eq!(req.param("lines"), Some("5"));
1052	        assert_eq!(req.bearer.as_deref(), Some("tok"));
1053	        assert_eq!(req.body, b"hi");
1054	        assert!(read_request(&mut r).unwrap().is_none());
1055	        let text = b"POST /x HTTP/1.1\r\nContent-Length: 100000\r\n\r\n";
1056	        let mut r = BufReader::new(&text[..]);
1057	        assert!(
1058	            read_request(&mut r).is_err(),
1059	            "an oversized body is refused before it is read"
1060	        );
1061	    }
1062	
1063	    #[test]
1064	    fn the_rate_window_slides() {
1065	        let t0 = Instant::now();
1066	        let mut w = RateWindow::new(2, Duration::from_secs(60));
1067	        assert!(w.allow(t0));
1068	        assert!(w.allow(t0 + Duration::from_secs(1)));
1069	        assert!(!w.allow(t0 + Duration::from_secs(2)));
1070	        assert!(w.allow(t0 + Duration::from_secs(61)));
1071	    }
1072	
1073	    #[test]
1074	    fn der_elements_walk_short_and_long_lengths() {
1075	        let short = [0x30, 0x02, 0x05, 0x00, 0xff];
1076	        let (tag, content, rest) = der_element(&short).unwrap();
1077	        assert_eq!((tag, content, rest), (0x30, &short[2..4], &short[4..]));
1078	        let long = [0x04, 0x82, 0x01, 0x00]
1079	            .into_iter()
1080	            .chain(std::iter::repeat_n(7u8, 256))
1081	            .collect::<Vec<_>>();
1082	        let (_, content, rest) = der_element(&long).unwrap();
1083	        assert_eq!(content.len(), 256);
1084	        assert!(rest.is_empty());
1085	        assert!(der_element(&[0x30, 0x05, 0x00]).is_none(), "a cut element");
1086	        assert!(spki_sha256_of_cert(b"not a certificate").is_none());
1087	    }
1088	}
