140	/// The pairing window: open it with a scope, or show the code it holds.
141	fn pairing(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
142	    theme::section(ui, "Pairing");
143	    let p = theme::palette(ui);
144	    if cx.core.identity_rotated() {
145	        ui.label(
146	            RichText::new(
147	                "The host's key was remade at this launch, so every earlier pairing is invalid. Pair each device again.",
148	            )
149	            .color(p.accent_2_text),
150	        );
151	    }
152	    let Some(identity) = cx.core.identity().cloned() else {
153	        return;
154	    };
155	    if let Some(window) = cx.core.pairing().cloned() {
156	        let port = cx.remote_port.unwrap_or(identity.listen.port);
157	        let address = remote::local_address()
158	            .map(|ip| format!("{ip}:{port}"))
159	            .unwrap_or_default();
160	        let payload = serde_json::json!({
161	            "server_id": identity.server_id,
162	            "spki_sha256": identity.spki_sha256,
163	            "code": window.code,
164	            "addresses": if address.is_empty() { Vec::new() } else { vec![address.clone()] },
165	        })
166	        .to_string();
167	        if draft
168	            .qr
169	            .as_ref()
170	            .is_none_or(|(code, _)| *code != window.code)
171	        {
172	            draft.qr = qr_texture(ui.ctx(), &payload).map(|t| (window.code.clone(), t));
173	        }
174	        ui.horizontal(|ui| {
175	            if let Some((_, texture)) = &draft.qr {
176	                ui.image(egui::load::SizedTexture::from_handle(texture));
177	            }
178	            ui.vertical(|ui| {
179	                ui.label(
180	                    RichText::new(spaced(&window.code))
181	                        .text_style(theme::h1())
182	                        .family(egui::FontFamily::Monospace),
183	                );
184	                ui.label(theme::meta_text(
185	                    ui,
186	                    format!("Key {}", short_hash(&identity.spki_sha256)),
187	                ));
188	                if !address.is_empty() {
189	                    ui.label(theme::meta_text(ui, format!("Address {address}")));
190	                }
191	                ui.label(theme::meta_text(
192	                    ui,
193	                    format!(
194	                        "Scan, or type the key and the code. Grants {} scope. Open for five minutes or three wrong codes.",
195	                        window.scope.word()
196	                    ),
197	                ));
198	                ui.horizontal(|ui| {
199	                    // The QR's text, for a client without a camera (the
200	                    // command-line browser takes it as one argument).
201	                    if theme::secondary(ui, "Copy invite")
202	                        .on_hover_text("The QR code's text, to paste into a client")
203	                        .clicked()
204	                    {
205	                        ui.ctx().copy_text(payload.clone());
206	                    }
207	                    if theme::secondary(ui, "Stop pairing").clicked() {
208	                        cx.dispatch(AppAction::ClosePairing);
209	                    }
210	                });
211	            });
212	        });
213	    } else {
214	        ui.horizontal(|ui| {
215	            ui.radio_value(&mut draft.scope, Scope::Read, "Read-only")
216	                .on_hover_text("Every view and the screen; nothing is sent into a session");
217	            ui.radio_value(&mut draft.scope, Scope::Control, "Control")
218	                .on_hover_text("Reads, and later the commands that type into a session");
219	            if theme::primary(ui, "Allow pairing for 5 minutes").clicked() {
220	                cx.dispatch(AppAction::OpenPairing {
221	                    code: remote::pairing_code(),
222	                    scope: draft.scope,
223	                });
224	            }
225	        });
226	    }
227	}
