:root {
  color-scheme: light dark;
  --fg: #1c1c1e;
  --muted: #6b6b70;
  --bg: #fafafa;
  --card: #ffffff;
  --line: #d8d8dc;
  --accent: #b3261e;
  --button: #2f5fd0;
}

@media (prefers-color-scheme: dark) {
  :root {
    --fg: #ececf0;
    --muted: #a0a0a8;
    --bg: #161618;
    --card: #222226;
    --line: #3a3a40;
    --accent: #ff8a80;
    --button: #7aa2ff;
  }
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--fg);
  background: var(--bg);
}

header {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}

header h1 { font-size: 20px; margin: 0; }

main { padding: 12px 16px 48px; max-width: 760px; }

h2 { font-size: 15px; margin: 20px 0 8px; color: var(--muted); }

.meta { color: var(--muted); font-size: 14px; }

.notice { padding: 12px; border: 1px solid var(--line); border-radius: 8px; background: var(--card); }

.row {
  display: block;
  width: 100%;
  text-align: left;
  padding: 10px 12px;
  margin: 0 0 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.row.waiting { border-color: var(--accent); border-width: 2px; }

.waiting-word { color: var(--accent); font-weight: 600; }

.name { font-weight: 600; }

pre.content {
  white-space: pre-wrap;
  word-break: break-word;
  font: 13px/1.4 ui-monospace, Menlo, monospace;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
  max-height: 60vh;
  overflow: auto;
}

textarea {
  width: 100%;
  min-height: 96px;
  font: inherit;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
  color: inherit;
}

button.action {
  margin-top: 8px;
  padding: 8px 16px;
  border: 0;
  border-radius: 8px;
  background: var(--button);
  color: #fff;
  font: inherit;
}

button.link {
  border: 0;
  background: none;
  color: var(--button);
  font: inherit;
  padding: 0;
  margin: 8px 0;
}

