/// The invite is the host's page with the code in the fragment, so
/// it never travels in a request; the address is the network one
/// only while the port listens there.
#[test]
fn the_invite_is_a_url_with_the_code_in_its_fragment() {
    use std::net::IpAddr;
    let mut core = loaded_core();
    core.dispatch(
        AppAction::OpenPairing {
            code: "abcd2345".into(),
            scope: Scope::Read,
        },
        Clock::at(0),
    );
    let window = core.pairing().unwrap().clone();
    let mut identity = core.identity().unwrap().clone();
    let lan: IpAddr = "192.168.1.9".parse().unwrap();
    let fragment = format!(
        "#code=ABCD2345&key={}&id={}",
        identity.spki_sha256, identity.server_id
    );

    let url = crate::core::invite_url(&identity, &window, Some(lan), 43187);
    assert_eq!(url, format!("https://127.0.0.1:43187/{fragment}"), "loopback");

    identity.listen.lan = true;
    let url = crate::core::invite_url(&identity, &window, Some(lan), 43187);
    assert_eq!(url, format!("https://192.168.1.9:43187/{fragment}"));
    assert!(!url.contains('?'), "nothing in a query: {url}");
    let (before, _) = url.split_once('#').unwrap();
    assert!(!before.contains("ABCD2345"), "the code is only in the fragment");

    let url = crate::core::invite_url(&identity, &window, None, 43187);
    assert!(url.starts_with("https://127.0.0.1:43187/#"), "no network: {url}");
    let v6: IpAddr = "fe80::1".parse().unwrap();
    let url = crate::core::invite_url(&identity, &window, Some(v6), 43187);
    assert!(url.starts_with("https://[fe80::1]:43187/#"), "{url}");
}

