// --- the web page

/// A reply with its head: the status, every header as sent, the body.
struct Response {
    status: u16,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

impl Response {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(n, _)| n.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    }

    fn json(&self) -> serde_json::Value {
        serde_json::from_slice(&self.body)
            .unwrap_or_else(|e| panic!("{e}: {}", String::from_utf8_lossy(&self.body)))
    }

    fn text(&self) -> String {
        String::from_utf8_lossy(&self.body).into_owned()
    }
}

type Tls = BufReader<StreamOwned<ClientConnection, TcpStream>>;

/// A pinned TLS connection, handshake done.
fn connect(addr: SocketAddr, config: &Arc<ClientConfig>) -> std::io::Result<Tls> {
    let tcp = TcpStream::connect(addr)?;
    tcp.set_read_timeout(Some(Duration::from_secs(10)))?;
    let conn = ClientConnection::new(
        Arc::clone(config),
        ServerName::try_from("localhost").unwrap(),
    )
    .map_err(std::io::Error::other)?;
    let mut s = StreamOwned::new(conn, tcp);
    while s.conn.is_handshaking() {
        s.conn.complete_io(&mut s.sock)?;
    }
    Ok(BufReader::new(s))
}

/// One request on `conn` with `headers` beside `Host: localhost`, and
/// its reply read whole.
fn exchange(
    conn: &mut Tls,
    method: &str,
    path: &str,
    headers: &[(&str, String)],
    body: &str,
) -> std::io::Result<Response> {
    let extra: String = headers
        .iter()
        .map(|(n, v)| format!("{n}: {v}\r\n"))
        .collect();
    write!(
        conn.get_mut(),
        "{method} {path} HTTP/1.1\r\nHost: localhost\r\n{extra}Content-Length: {}\r\n\r\n{body}",
        body.len()
    )?;
    conn.get_mut().flush()?;
    let mut line = String::new();
    conn.read_line(&mut line)?;
    let status: u16 = line
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, line.clone()))?;
    let mut headers = Vec::new();
    loop {
        let mut h = String::new();
        conn.read_line(&mut h)?;
        let h = h.trim_end();
        if h.is_empty() {
            break;
        }
        if let Some((n, v)) = h.split_once(':') {
            headers.push((n.trim().to_owned(), v.trim().to_owned()));
        }
    }
    let length = headers
        .iter()
        .find(|(n, _)| n.eq_ignore_ascii_case("content-length"))
        .and_then(|(_, v)| v.parse().ok())
        .unwrap_or(0);
    let mut body = vec![0; length];
    conn.read_exact(&mut body)?;
    Ok(Response {
        status,
        headers,
        body,
    })
}

/// A page file over a fresh connection: answered on the connection
/// thread, so the frame need not serve.
fn page_load(
    addr: SocketAddr,
    config: &Arc<ClientConfig>,
    path: &str,
) -> std::io::Result<Response> {
    exchange(&mut connect(addr, config)?, "GET", path, &[], "")
}

/// A page load that waits out a slot still being given back: the
/// previous load's thread frees its slot a moment after the client
/// sees the close.
fn page_load_retrying(port: &Port, path: &str) -> Response {
    let mut last = None;
    for _ in 0..50 {
        match page_load(port.addr, &port.client, path) {
            Ok(r) => return r,
            Err(e) => last = Some(e),
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    panic!("no page: {last:?}");
}

/// A request from a client thread with `headers`, served by the app on
/// this thread.
fn call_with(
    port: &mut Port,
    method: &str,
    path: &str,
    headers: &[(&str, String)],
    body: &str,
) -> Response {
    let addr = port.addr;
    let config = Arc::clone(&port.client);
    let (method, path, body) = (method.to_owned(), path.to_owned(), body.to_owned());
    let headers: Vec<(String, String)> = headers
        .iter()
        .map(|(n, v)| ((*n).to_owned(), v.clone()))
        .collect();
    let client = std::thread::spawn(move || {
        let headers: Vec<(&str, String)> = headers
            .iter()
            .map(|(n, v)| (n.as_str(), v.clone()))
            .collect();
        exchange(&mut connect(addr, &config)?, &method, &path, &headers, &body)
    });
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    while !client.is_finished() {
        assert!(std::time::Instant::now() < deadline, "no reply");
        port.app.serve_pending();
        std::thread::sleep(Duration::from_millis(2));
    }
    client.join().unwrap().expect("http")
}

fn cookie(value: &str) -> (&'static str, String) {
    ("Cookie", value.to_owned())
}

/// The identity's key, as the QR carries it.
fn spki(port: &Port) -> String {
    port.remote
        .state()
        .identity
        .as_ref()
        .unwrap()
        .spki_sha256
        .clone()
}

/// Pair as a browser does: `/info`, then `/pair` asking for the cookie.
/// The reply, whose `Set-Cookie` carries the token.
fn pair_browser(port: &mut Port, code: &str, scope: Scope) -> Response {
    port.app.dispatch(AppAction::OpenPairing {
        code: code.into(),
        scope,
    });
    let (status, info) = get(port, "/api/v1/info", None);
    assert_eq!(status, 200);
    assert_eq!(info["body"]["spki_sha256"], spki(port));
    let body = serde_json::json!({
        "code": code,
        "spki_sha256": spki(port),
        "device_name": "Safari on iPhone",
        "transport": "cookie",
    });
    let reply = call_with(port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(reply.status, 200, "{}", reply.text());
    reply
}

/// `name=value` from a reply's `Set-Cookie`, and its attributes.
fn set_cookie(reply: &Response) -> (String, Vec<String>) {
    let header = reply.header("Set-Cookie").expect("a cookie");
    let mut parts = header.split(';').map(|p| p.trim().to_owned());
    let pair = parts.next().unwrap();
    (pair, parts.collect())
}

/// A second, native pairing on the same host: its token.
fn native_pair(port: &mut Port) -> String {
    pair(port, "NATV2345", Scope::Control, "Pad")
}

/// The page's three files answer anyone, each with its type and the
/// headers that keep a browser to the page's own files, and close the
/// connection; anything else still gets the frame's JSON 404.
#[test]
fn the_page_is_served_to_anyone_with_its_headers_and_nothing_else_is() {
    use switchboard::adapters::web;
    let mut port = port();
    assert_eq!(
        web::CSP,
        "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
    );
    for page in &web::PAGES {
        let reply = page_load(port.addr, &port.client, page.path).expect("page");
        assert_eq!(reply.status, 200, "{}", page.path);
        assert_eq!(reply.header("Content-Type"), Some(page.content_type));
        assert_eq!(reply.header("Content-Security-Policy"), Some(web::CSP));
        assert_eq!(reply.header("Cache-Control"), Some("no-store"));
        assert_eq!(reply.header("X-Content-Type-Options"), Some("nosniff"));
        assert_eq!(reply.header("Referrer-Policy"), Some("no-referrer"));
        assert_eq!(reply.header("Connection"), Some("close"));
        assert_eq!(reply.body, page.body);
    }
    let reply = page_load(port.addr, &port.client, "/?code=ZZZZ9999&key=ab").expect("page");
    assert_eq!(reply.status, 200, "a query on a page path is ignored");
    assert!(!reply.text().contains("ZZZZ9999"), "and never echoed");

    for (method, path) in [("GET", "/favicon.ico"), ("POST", "/"), ("GET", "/api")] {
        let reply = call_with(&mut port, method, path, &[], "");
        assert_eq!(reply.status, 404, "{method} {path}");
        assert_eq!(code(&reply.json()), "not_found", "{method} {path}");
    }
    let reply = call_with(&mut port, "GET", "/api/v1/info", &[], "");
    assert_eq!(reply.header("Cache-Control"), Some("no-store"));
    assert_eq!(reply.header("X-Content-Type-Options"), Some("nosniff"));
    assert_eq!(reply.header("Connection"), Some("keep-alive"));
}

/// The page names only what the host serves: its own files, and API
/// paths that are routes; and it has no inline script or style and no
/// way to turn the host's text into markup.
#[test]
fn the_embedded_page_names_only_what_the_host_serves() {
    use switchboard::adapters::web;
    let html = String::from_utf8(web::PAGES[0].body.to_vec()).unwrap();
    let js = String::from_utf8(web::page("/app.js").unwrap().body.to_vec()).unwrap();
    let attribute_values = |text: &str, attr: &str| -> Vec<String> {
        text.split(&format!("{attr}=\""))
            .skip(1)
            .map(|rest| rest.split('"').next().unwrap().to_owned())
            .collect()
    };
    let named: Vec<String> = attribute_values(&html, " src")
        .into_iter()
        .chain(attribute_values(&html, " href"))
        .collect();
    assert!(named.len() >= 3, "{named:?}");
    for value in named {
        assert!(
            value.starts_with("data:") || web::page(&value).is_some(),
            "{value} is not served"
        );
    }
    let scripts = html.matches("<script").count();
    assert_eq!(
        scripts,
        html.matches("<script src=").count(),
        "inline script"
    );
    assert!(!html.contains("style="), "inline style");
    let lower = html.to_ascii_lowercase();
    for (i, _) in lower.match_indices(" on") {
        let name: String = lower[i + 3..]
            .chars()
            .take_while(char::is_ascii_alphabetic)
            .collect();
        assert!(
            !lower[i + 3 + name.len()..].starts_with('='),
            "an inline handler: on{name}"
        );
    }
    for banned in [
        "innerHTML",
        "outerHTML",
        "insertAdjacentHTML",
        "eval(",
        "document.write",
        "new Function",
    ] {
        assert!(!js.contains(banned), "{banned} in app.js");
    }

    let mut port = port();
    let (_, project, session) = seed(&mut port, "");
    let token = pair(&mut port, "ABCD2345", Scope::Control, "Pad");
    let paths: Vec<&str> = js
        .split("'/api/v1/")
        .skip(1)
        .map(|rest| rest.split('\'').next().unwrap())
        .collect();
    assert!(paths.len() >= 10, "{paths:?}");
    for path in paths {
        let path = format!("/api/v1/{path}")
            .replace("/projects/{id}", &format!("/projects/{project}"))
            .replace("/sessions/{id}", &format!("/sessions/{session}"));
        assert!(!path.contains('{'), "{path}");
        let method = if path.ends_with("/pair") || path.ends_with("/send") {
            "POST"
        } else {
            "GET"
        };
        let (status, reply) = call(&mut port, method, &path, Some(&token), "{}");
        let message = reply["error"]["message"].as_str().unwrap_or("");
        assert!(
            !(status == 404
                && ["no such endpoint", "not available on this port"].contains(&message)),
            "{method} {path} is not a route: {reply}"
        );
    }
}

/// A browser pairs from the page: the token arrives as an `HttpOnly`
/// cookie named for the host, never in the body, and the cookie alone
/// reads. Two instances on one Mac share a browser's cookie jar, so
/// each reads only the cookie with its own server id.
#[test]
fn a_browser_pairs_by_cookie_named_for_its_host_and_a_native_pairing_is_unchanged() {
    let mut a = port();
    let reply = pair_browser(&mut a, "ABCD2345", Scope::Read);
    let body = reply.json();
    let server_id = body["body"]["server_id"].as_str().unwrap().to_owned();
    assert!(
        body["body"].get("token").is_none(),
        "no token in the body: {body}"
    );
    let (pair_a, attributes) = set_cookie(&reply);
    let (name, token) = pair_a.split_once('=').unwrap();
    assert_eq!(name, format!("__Host-sb-{server_id}"));
    assert_eq!(token.len(), 43);
    for wanted in ["HttpOnly", "Secure", "SameSite=Strict", "Path=/"] {
        assert!(
            attributes.iter().any(|a| a == wanted),
            "{wanted}: {attributes:?}"
        );
    }
    assert!(
        !attributes
            .iter()
            .any(|a| a.to_ascii_lowercase().starts_with("domain")),
        "{attributes:?}"
    );
    let device_a = a.app.core().devices()[0].clone();
    assert_eq!(device_a.name, "Safari on iPhone");
    assert_eq!(device_a.token_sha256, remote::token_sha256(token));

    let me = call_with(&mut a, "GET", "/api/v1/me", &[cookie(&pair_a)], "");
    assert_eq!(me.status, 200, "{}", me.text());
    let me = me.json();
    assert_eq!(me["body"]["device_id"], device_a.id.to_string());
    assert_eq!(me["body"]["name"], "Safari on iPhone");
    assert_eq!(me["body"]["scope"], "read");
    assert_eq!(me["body"]["server_id"], server_id);
    assert!(me["body"]["server_name"].is_string());

    // A native client's pairing is as it was: the token in the body.
    a.app.dispatch(AppAction::OpenPairing {
        code: "WXYZ6789".into(),
        scope: Scope::Read,
    });
    let native =
        serde_json::json!({ "code": "WXYZ6789", "device_name": "Pad", "spki_sha256": spki(&a) });
    let reply = call_with(&mut a, "POST", "/api/v1/pair", &[], &native.to_string());
    assert_eq!(reply.status, 200);
    assert!(reply.header("Set-Cookie").is_none());
    assert_eq!(reply.json()["body"]["token"].as_str().unwrap().len(), 43);

    // A second instance: another name, and each host reads its own.
    let mut b = port();
    let (pair_b, _) = set_cookie(&pair_browser(&mut b, "ABCD2345", Scope::Read));
    assert_ne!(
        pair_a.split_once('=').unwrap().0,
        pair_b.split_once('=').unwrap().0
    );
    let both = cookie(&format!("theme=dark; {pair_a}; {pair_b}"));
    let device_b = b.app.core().devices()[0].id;
    let me = call_with(&mut a, "GET", "/api/v1/me", std::slice::from_ref(&both), "");
    assert_eq!(me.json()["body"]["device_id"], device_a.id.to_string());
    let me = call_with(&mut b, "GET", "/api/v1/me", &[both], "");
    assert_eq!(me.json()["body"]["device_id"], device_b.to_string());
    let other = call_with(&mut a, "GET", "/api/v1/me", &[cookie(&pair_b)], "");
    assert_eq!((other.status, code(&other.json())), (401, "unauthorized"));
    let fixed = cookie(&format!("__Host-sb={token}"));
    let reply = call_with(&mut a, "GET", "/api/v1/me", &[fixed], "");
    assert_eq!((reply.status, code(&reply.json())), (401, "unauthorized"));
}

/// A write or an upgrade by cookie alone must carry this host's own
/// origin; a bearer needs none, and a read by cookie needs none.
#[test]
fn a_write_by_cookie_must_come_from_the_hosts_page() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let (pair, _) = set_cookie(&pair_browser(&mut port, "ABCD2345", Scope::Control));
    let send = format!("/api/v1/sessions/{session}/send");
    let body = r#"{"op":"web-1","text":"hello"}"#;
    for origin in [
        None,
        Some("https://evil.example"),
        Some("http://localhost"),
        Some("https://localhost:1"),
    ] {
        let mut headers = vec![cookie(&pair)];
        headers.extend(origin.map(|o| ("Origin", o.to_owned())));
        let reply = call_with(&mut port, "POST", &send, &headers, body);
        assert_eq!(
            (reply.status, code(&reply.json())),
            (403, "origin"),
            "{origin:?}"
        );
    }
    let own = ("Origin", "https://localhost".to_owned());
    let reply = call_with(
        &mut port,
        "POST",
        &send,
        &[cookie(&pair), own.clone()],
        body,
    );
    assert_ne!(code(&reply.json()), "origin", "{}", reply.text());
    assert_ne!(reply.status, 401);

    let token = native_pair(&mut port);
    let reply = call_with(
        &mut port,
        "POST",
        &send,
        &[("Authorization", format!("Bearer {token}"))],
        r#"{"op":"native-1","text":"hello"}"#,
    );
    assert_ne!(code(&reply.json()), "origin", "{}", reply.text());
    let reply = call_with(&mut port, "GET", "/api/v1/waiting", &[cookie(&pair)], "");
    assert_eq!(reply.status, 200, "a read by cookie needs no Origin");

    let foreign = subscribe_with(
        &mut port,
        "/api/v1/events",
        &[cookie(&pair), ("Origin", "https://evil.example".to_owned())],
    );
    assert!(foreign.is_err(), "a cross-origin upgrade is refused");
    let own = subscribe_with(&mut port, "/api/v1/events", &[cookie(&pair), own]);
    assert!(own.is_ok(), "{:?}", own.err());
}

/// `/me` follows the scope the dialog sets, and after a revocation the
/// cookie is refused while `/info` still names the same host, which is
/// how the page tells "removed on the host" from "identity changed".
#[test]
fn me_follows_the_scope_and_a_revoked_browser_can_tell_it_was_removed() {
    let mut port = port();
    let (_, info) = get(&mut port, "/api/v1/info", None);
    let (pair, _) = set_cookie(&pair_browser(&mut port, "ABCD2345", Scope::Read));
    let me = call_with(&mut port, "GET", "/api/v1/me", &[cookie(&pair)], "");
    assert_eq!(me.json()["body"]["scope"], "read");
    let id = port.app.core().devices()[0].id;
    port.app.dispatch(AppAction::SetDeviceScope {
        device: id,
        scope: Scope::Control,
    });
    let me = call_with(&mut port, "GET", "/api/v1/me", &[cookie(&pair)], "");
    assert_eq!(me.json()["body"]["scope"], "control");
    port.app.dispatch(AppAction::RevokeDevice(id));
    let me = call_with(&mut port, "GET", "/api/v1/me", &[cookie(&pair)], "");
    assert_eq!((me.status, code(&me.json())), (401, "unauthorized"));
    let (_, after) = get(&mut port, "/api/v1/info", None);
    assert_eq!(after["body"]["server_id"], info["body"]["server_id"]);
    assert_eq!(after["body"]["spki_sha256"], info["body"]["spki_sha256"]);
    let (status, reply) = get(&mut port, "/api/v1/me", None);
    assert_eq!((status, code(&reply)), (401, "unauthorized"), "unpaired");
}

/// A page load closes its connection, so four browsers that keep theirs
/// open still leave a slot for a fifth; and the page has a window of
/// its own, which leaves `/info` and `/pair` theirs.
#[test]
fn a_page_load_frees_its_slot_and_has_its_own_window() {
    let mut port = port();
    let mut held = Vec::new();
    for _ in 0..MAX_UNAUTHENTICATED {
        let mut conn = connect(port.addr, &port.client).expect("connect");
        let reply = exchange(&mut conn, "GET", "/", &[], "").expect("page");
        assert_eq!(reply.status, 200);
        let mut buf = [0u8; 1];
        let closed = matches!(conn.get_mut().read(&mut buf), Ok(0) | Err(_));
        assert!(closed, "the host closed after the page");
        held.push(conn);
    }
    let fifth = page_load_retrying(&port, "/app.css");
    assert_eq!(fifth.status, 200, "the slots came back");
    drop(held);

    // Five loads so far; the window allows `PAGE_PER_MINUTE`.
    for _ in 5..remote::PAGE_PER_MINUTE {
        assert_eq!(page_load_retrying(&port, "/app.js").status, 200);
    }
    let over = page_load_retrying(&port, "/");
    assert_eq!(over.status, 429);
    assert_eq!(code(&over.json()), "rate_limited");
    let (status, _) = get(&mut port, "/api/v1/info", None);
    assert_eq!(status, 200, "info keeps its own window");
    let (status, reply) = call(&mut port, "POST", "/api/v1/pair", None, "{}");
    assert_eq!((status, code(&reply)), (403, "pairing_closed"), "and pair");
}

