/// One of the page's files, inside the page window: `true` once it is
/// written and the TLS session closed, so the connection ends; `false`
/// after a 429, which keeps it.
fn serve_page(
    stream: &mut StreamOwned<ServerConnection, TcpStream>,
    shared: &Shared,
    page: &web::Page,
) -> io::Result<bool> {
    if Limits::over(&shared.limits.page) {
        respond_limited(stream)?;
        return Ok(false);
    }
    respond_page(stream, page)?;
    stream.conn.send_close_notify();
    stream.flush()?;
    Ok(true)
}

fn respond_limited<W: Write>(w: &mut W) -> io::Result<()> {
    respond(
        w,
        429,
        &error_body("rate_limited", "too many requests; try again in a minute"),
        &[],
    )
}

