    /// The invite from the scanned or pasted text: the host's link,
    /// `https://<address>/#code=…&key=…&id=…`, as the pairing window
    /// shows it, or the JSON an older host showed.
    public static func parse(_ text: String) throws -> PairingInvite {
        let text = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard text.hasPrefix("https://") else {
            return try Wire.decode(PairingInvite.self, from: Data(text.utf8))
        }
        let rest = text.dropFirst("https://".count)
        guard let hash = rest.firstIndex(of: "#") else { throw InviteError.incomplete }
        // The authority as written, so an IPv6 address keeps its
        // brackets the way `Address` reads them.
        let address = String(rest[..<hash].prefix { $0 != "/" })
        var values: [String: String] = [:]
        for pair in rest[rest.index(after: hash)...].split(separator: "&") {
            let parts = pair.split(separator: "=", maxSplits: 1)
            guard parts.count == 2 else { continue }
            values[String(parts[0])] = String(parts[1]).removingPercentEncoding
        }
        guard let code = values["code"], !code.isEmpty,
              let key = values["key"], !key.isEmpty,
              let id = values["id"], !id.isEmpty
        else { throw InviteError.incomplete }
        return PairingInvite(
            serverID: ServerID(id), spkiSha256: key, code: code,
            addresses: address.isEmpty ? [] : [address])
    }
}

/// Why a pasted link is not an invite.
public enum InviteError: Error, Equatable {
    /// The link lacks the code, the key or the id.
    case incomplete
}

